// FleetLoadoutsEntryWireExtent: the extent FleetLoadoutsEntry's maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool FleetLoadoutsEntryWireExtent( const uint8_t * body, int64_t length, int64_t & at )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch );
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { return true; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) { return true; }
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0x9194 && field_kind == 14 ) // value
        {
            if ( !r.has( 4 ) ) { return true; }
            uint32_t map_len = r.get32();
            if ( !r.has( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetLoadoutsEntryValueEntry ), (int64_t) alignof( FleetLoadoutsEntryValueEntry ), NULL ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

// FleetLoadoutsEntryMapExtentAt: the node extent FleetLoadoutsEntry's maps take, PRE-ORDER, advancing the
// running offset exactly as FleetLoadoutsEntryMapPack advances it (docs/SPEC-TABLES.md §2.8).
template <typename Ctx>
inline bool FleetLoadoutsEntryMapExtentAt( const Ctx & ctx, const FleetLoadoutsEntry & value, int64_t & at )
{
    {
        TableMapCursor<FleetLoadoutsEntryValueEntry> cursor = TableMapOrder( ctx, value.value );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetLoadoutsEntryValueEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntryValueEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    return true;
}

// the whole extent of one node, from a fresh offset: what a pack reserves
// for it beside the record's own storage.
template <typename Ctx>
inline int64_t FleetLoadoutsEntryMapExtent( const Ctx & ctx, const FleetLoadoutsEntry & value )
{
    int64_t at = 0;
    if ( !FleetLoadoutsEntryMapExtentAt( ctx, value, at ) ) { return -1; }
    return at;
}

// FleetLoadoutsEntryMapPack: carve FleetLoadoutsEntry's map arrays out of the node's extent and copy the
// entries in ASCENDING key order, PRE-ORDER, advancing the same running
// offset FleetLoadoutsEntryMapExtentAt advances (docs/SPEC-TABLES.md §2.8).
template <typename Ctx>
inline bool FleetLoadoutsEntryMapPack( const Ctx & ctx, const FleetLoadoutsEntry & src, FleetLoadoutsEntry & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableMapCursor<FleetLoadoutsEntryValueEntry> cursor = TableMapOrder( ctx, src.value );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntryValueEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetLoadoutsEntryValueEntry * placed = (FleetLoadoutsEntryValueEntry *) ( extent + at );
        at += bytes;
        dst.value.count = cursor.count;
        dst.value.padding = 0;
        dst.value.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.value.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetLoadoutsEntryValueEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    return true;
}

// FleetWireExtent: the extent Fleet's maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool FleetWireExtent( const uint8_t * body, int64_t length, int64_t & at )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch );
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { return true; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) { return true; }
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0x2d39 && field_kind == 14 ) // ships
        {
            if ( !r.has( 4 ) ) { return true; }
            uint32_t map_len = r.get32();
            if ( !r.has( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetShipsEntry ), (int64_t) alignof( FleetShipsEntry ), NULL ) ) { return false; }
            continue;
        }
        if ( field_id == 0xff83 && field_kind == 14 ) // by_id
        {
            if ( !r.has( 4 ) ) { return true; }
            uint32_t map_len = r.get32();
            if ( !r.has( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetByIdEntry ), (int64_t) alignof( FleetByIdEntry ), NULL ) ) { return false; }
            continue;
        }
        if ( field_id == 0xd91b && field_kind == 14 ) // loadouts
        {
            if ( !r.has( 4 ) ) { return true; }
            uint32_t map_len = r.get32();
            if ( !r.has( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetLoadoutsEntry ), (int64_t) alignof( FleetLoadoutsEntry ), &FleetLoadoutsEntryWireExtent ) ) { return false; }
            continue;
        }
        if ( field_id == 0x61ae && field_kind == 14 ) // tiers
        {
            if ( !r.has( 4 ) ) { return true; }
            uint32_t map_len = r.get32();
            if ( !r.has( map_len ) ) { return true; }
            const uint8_t * map_body = r.buffer + r.offset;
            r.offset += map_len;
            if ( !TableMapWireExtent( map_body, (int64_t) map_len, at, (int64_t) sizeof( FleetTiersEntry ), (int64_t) alignof( FleetTiersEntry ), NULL ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

// FleetMapExtentAt: the node extent Fleet's maps take, PRE-ORDER, advancing the
// running offset exactly as FleetMapPack advances it (docs/SPEC-TABLES.md §2.8).
template <typename Ctx>
inline bool FleetMapExtentAt( const Ctx & ctx, const Fleet & value, int64_t & at )
{
    {
        TableMapCursor<FleetShipsEntry> cursor = TableMapOrder( ctx, value.ships );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetShipsEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetShipsEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetByIdEntry> cursor = TableMapOrder( ctx, value.by_id );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( FleetByIdEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetByIdEntry ); // the whole array FIRST
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, entry by entry in key order
        {
            if ( !FleetByIdEntryMapExtentAt( ctx, *cursor[i], at ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetLoadoutsEntry> cursor = TableMapOrder( ctx, value.loadouts );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( FleetLoadoutsEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntry ); // the whole array FIRST
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, entry by entry in key order
        {
            if ( !FleetLoadoutsEntryMapExtentAt( ctx, *cursor[i], at ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetTiersEntry> cursor = TableMapOrder( ctx, value.tiers );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( FleetTiersEntry )
        at += (int64_t) cursor.count * (int64_t) sizeof( FleetTiersEntry ); // the whole array FIRST
        TableMapRelease( cursor );
    }
    return true;
}

// the whole extent of one node, from a fresh offset: what a pack reserves
// for it beside the record's own storage.
template <typename Ctx>
inline int64_t FleetMapExtent( const Ctx & ctx, const Fleet & value )
{
    int64_t at = 0;
    if ( !FleetMapExtentAt( ctx, value, at ) ) { return -1; }
    return at;
}

// FleetMapPack: carve Fleet's map arrays out of the node's extent and copy the
// entries in ASCENDING key order, PRE-ORDER, advancing the same running
// offset FleetMapExtentAt advances (docs/SPEC-TABLES.md §2.8).
template <typename Ctx>
inline bool FleetMapPack( const Ctx & ctx, const Fleet & src, Fleet & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableMapCursor<FleetShipsEntry> cursor = TableMapOrder( ctx, src.ships );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetShipsEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetShipsEntry * placed = (FleetShipsEntry *) ( extent + at );
        at += bytes;
        dst.ships.count = cursor.count;
        dst.ships.padding = 0;
        dst.ships.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.ships.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetShipsEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetByIdEntry> cursor = TableMapOrder( ctx, src.by_id );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetByIdEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetByIdEntry * placed = (FleetByIdEntry *) ( extent + at );
        at += bytes;
        dst.by_id.count = cursor.count;
        dst.by_id.padding = 0;
        dst.by_id.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.by_id.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetByIdEntry ) ); // trivially copyable, by construction
        }
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            if ( !FleetByIdEntryMapPack( ctx, *cursor[i], placed[i], extent, at, capacity ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetLoadoutsEntry> cursor = TableMapOrder( ctx, src.loadouts );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetLoadoutsEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetLoadoutsEntry * placed = (FleetLoadoutsEntry *) ( extent + at );
        at += bytes;
        dst.loadouts.count = cursor.count;
        dst.loadouts.padding = 0;
        dst.loadouts.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.loadouts.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetLoadoutsEntry ) ); // trivially copyable, by construction
        }
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            if ( !FleetLoadoutsEntryMapPack( ctx, *cursor[i], placed[i], extent, at, capacity ) ) { TableMapRelease( cursor ); return false; }
        }
        TableMapRelease( cursor );
    }
    {
        TableMapCursor<FleetTiersEntry> cursor = TableMapOrder( ctx, src.tiers );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3;
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( FleetTiersEntry );
        if ( at + bytes > capacity ) { TableMapRelease( cursor ); return false; }
        FleetTiersEntry * placed = (FleetTiersEntry *) ( extent + at );
        at += bytes;
        dst.tiers.count = cursor.count;
        dst.tiers.padding = 0;
        dst.tiers.entries.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.tiers.entries ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            memcpy( (void *) ( placed + i ), (const void *) cursor[i], sizeof( FleetTiersEntry ) ); // trivially copyable, by construction
        }
        TableMapRelease( cursor );
    }
    return true;
}

// ---- FleetLoadoutsEntry.value: the builder's five and the side index (§2.8) ----

// INSERT: the key is copied, the value is handed back at its defaults to
// fill. A DUPLICATE key REPLACES — the value is reset and the same entry
// handed back, key and address unchanged — so a caller that wants to know
// writes Find first. NULL is NOT INSERTED: a key longer than the bound,
// because a truncated key would be a merged entry, and an arena that
// cannot carve another segment, alike.
inline Item * FleetLoadoutsEntryValueInsert( TableWorker & worker, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    if ( worker.arena == NULL ) { return NULL; }
    FleetLoadoutsEntryValueEntry * found = TableMapScan( *worker.arena, map, key ); // one LINEAR SCAN of the live entries
    if ( found != NULL )
    {
        TableResetMapValue( *found ); // a duplicate REPLACES: the value goes back to its defaults
        return TableEntryValue( found );
    }
    TableMapHead * head = TableMapReach( worker, map );
    if ( head == NULL ) { return NULL; }
    FleetLoadoutsEntryValueEntry * entry = TableMapAppend( worker, head, map ); // APPENDS; nothing ever moves (§6.4)
    if ( entry == NULL ) { return NULL; }
    TableReset( *entry );
    TableEntrySetKey( *entry, key );
    return TableEntryValue( entry );
}

// FIND on the builder: the same linear scan, O( n ) key compares over the
// segments in insertion order. NULL when absent. The builder builds NO
// INDEX, and that is a rule — the sort happens once, at Lock, Save or
// Cook, and every lookup that matters runs over the sorted region.
inline Item * FleetLoadoutsEntryValueFind( TableArena & arena, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    FleetLoadoutsEntryValueEntry * found = TableMapScan( arena, map, key );
    return found != NULL ? TableEntryValue( found ) : NULL;
}

// ERASE: marks the entry DEAD, one bit in the segment's slot and not in the
// entry table. False when absent. Its storage is held until the builder
// resets and never reused mid-build, because reusing a slot would make "an
// entry's address is stable" false for exactly one case.
inline bool FleetLoadoutsEntryValueErase( TableArena & arena, TableMap<FleetLoadoutsEntryValueEntry> & map, uint8_t key )
{
    return TableMapErase( arena, map, key );
}

// EACH on the builder: INSERTION order, live entries only.
