// where it landed, so a node's FIRST reference lays it out and every later
// reference points BACK at that one body. A region delta therefore has no
// required sign (§6.3), and sharing and a back-reference are one fact. A
// reference to a node whose descent is still OPEN is a cycle, and this
// refuses it rather than packing one.
template <typename Ctx>
inline bool FleetPackEdges( const Ctx & ctx, TablePackMap & seen, const Fleet & src, Fleet & dst, uint8_t * base, int64_t capacity, int64_t & used );

template <typename Ctx>
inline bool FleetPack( const Ctx & ctx, TablePackMap & seen, const Fleet & src, Fleet & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    memcpy( (void *) &dst, (const void *) &src, sizeof( Fleet ) ); // trivially copyable, by construction
    int64_t at = 0;
    uint8_t * extent = (uint8_t *) &dst + TableAlignUp64( (int64_t) sizeof( Fleet ) );
    const int64_t room = capacity - ( (int64_t) ( extent - base ) );
    if ( !FleetMapPack( ctx, src, dst, extent, at, room ) ) { return false; }
    return FleetPackEdges( ctx, seen, src, dst, base, capacity, used );
}

template <typename Ctx>
inline bool FleetPackEdges( const Ctx & ctx, TablePackMap & seen, const Fleet & src, Fleet & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    { // by_id: a by-value edge, entries in ASCENDING key order (§2.8, §3.1)
        TableMapCursor<FleetByIdEntry> cursor_by_id = TableMapOrder( ctx, src.by_id );
        if ( !cursor_by_id.ok ) { return false; }
        FleetByIdEntry * placed_by_id = (FleetByIdEntry *) ( dst.by_id.entries.value != 0 ? ( (uint8_t *) &dst.by_id.entries + dst.by_id.entries.value ) : NULL );
        for ( int32_t i = 0; i < cursor_by_id.count; i++ )
        {
            if ( !FleetByIdEntryPackEdges( ctx, seen, *cursor_by_id[i], placed_by_id[i], base, capacity, used ) ) { TableMapRelease( cursor_by_id ); return false; }
        }
        TableMapRelease( cursor_by_id );
    }
    {
        dst.flagship.value = 0; // flagship
        const ShipConfig * pointee = ShipConfigAt( ctx, src.flagship );
        if ( pointee != NULL )
        {
            int64_t at = TableAlignUp64( used ); // where it WOULD land, if this is its first visit
            bool taken = false;
            int64_t slot = 0;
            const TablePackEntry * entry = TablePackMapReach( seen, (const void *) pointee, at, taken, slot );
            if ( entry == NULL ) { return false; } // the map could not grow
            if ( !taken )
            {
                if ( entry->open != 0 ) { return false; } // a data cycle
                dst.flagship.value = (int64_t) ( ( base + entry->offset ) - (const uint8_t *) &dst.flagship ); // the one body it already has
            }
            else
            {
                if ( at + (int64_t) sizeof( ShipConfig ) > capacity ) { return false; }
                used = at + TableAlignUp64( (int64_t) sizeof( ShipConfig ) );
                ShipConfig * child = new ( base + at ) ShipConfig; // lifetime only: the Pack below memcpy's the whole node over it
                dst.flagship.value = (int64_t) ( ( base + at ) - (const uint8_t *) &dst.flagship );
                if ( !ShipConfigPack( ctx, seen, *pointee, *child, base, capacity, used ) ) { return false; }
                TablePackMapClose( seen, (const void *) pointee, slot );
            }
        }
    }
    return true;
}

// ---- Fleet: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: FleetBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Fleet is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct FleetBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    FleetBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Fleet> slot = main.Alloc<Fleet>();
        root_ref = slot.ref;
    }
    ~FleetBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    FleetBuilder( const FleetBuilder & ) = delete;
    FleetBuilder & operator=( const FleetBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Fleet * GetRoot() { return arena.locked ? NULL : (Fleet *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Fleet * AsConst() const { return (const Fleet *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool FleetBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Fleet & root = *(const Fleet *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = FleetPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t root_extent = FleetMapExtent( ctx, root );
    if ( root_extent < 0 ) { TablePackMapShutdown( seen ); return false; } // the sort could not run
    int64_t total = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Fleet ) ) + root_extent ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Fleet ) ) + root_extent );
    Fleet * destination = new ( packed ) Fleet; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !FleetPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Fleet on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// FleetNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides.
// A MAP'S ENTRIES RIDE IN THEIR HOLDER'S EXTENT (docs/SPEC-TABLES.md §2.8),
// so a record's storage is its type's PLUS N x sizeof( Entry ) at every
// depth, summed from the FRAMING: N is framing and not a value, and this
// reads no field. kTableNodeRefused is a wire whose N its L cannot carry.
inline int64_t FleetNodeStorage( uint64_t type_id, int64_t length )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0x758252d2d1b14f0dull: return TableAlignUp64( (int64_t) sizeof( ShipConfig ) ); // ShipConfig
        default: break;
    }
    return -1;
}

// FleetNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void FleetNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x758252d2d1b14f0dull: { ShipConfig * node = new ( at ) ShipConfig; ShipConfigReset( *node ); break; } // ShipConfig
        default: break;
    }
}

// FleetNodeRecordBytes: one record's OWN storage, before the extent its maps
// take (docs/SPEC-TABLES.md §2.8) — where a node's extent begins.
inline int64_t FleetNodeRecordBytes( uint64_t type_id )
{
    switch ( type_id )
    {
        case 0x758252d2d1b14f0dull: return TableAlignUp64( (int64_t) sizeof( ShipConfig ) ); // ShipConfig
        default: break;
    }
    return 0;
}

// FleetNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t FleetNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x758252d2d1b14f0dull: return (uint32_t) worker.Alloc<ShipConfig>().ref.value; // ShipConfig
        default: break;
    }
    return 0;
}

// FleetNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void FleetNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    // the node's own EXTENT, where its maps' entry arrays are carved from,
    // PRE-ORDER as the bodies decode (docs/SPEC-TABLES.md §2.8). The tool's
    // path carries a worker instead: there the entries are the arena's.
    TableMapCarve carve;
    carve.worker = nodes.worker;
    if ( carve.worker == NULL )
    {
        const int64_t storage = FleetNodeStorage( type_id, r.size );
        const int64_t record = storage > 0 ? FleetNodeRecordBytes( type_id ) : 0;
        carve.at = at + record;
        carve.left = storage > record ? storage - record : 0;
    }
    nodes.carve = &carve;
    (void) nodes; // every node this root can name is a FIXED table
    switch ( type_id )
    {
        case 0x758252d2d1b14f0dull: ShipConfigLoadBody( r, *(ShipConfig *) at ); break; // ShipConfig
        default: break;
    }
    nodes.carve = NULL; // the cursor is ONE node's, and this node's body is done
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool FleetNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Fleet & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return FleetNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t FleetMeasureWire( const Ctx & ctx, const Fleet & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( FleetNumberFrom( ctx, numbering, root ) )
    {
        bytes = FleetMeasureBody( ctx, root );
        if ( bytes >= 0 )
        {
            int64_t table = TableNodeTableMeasure( ctx, numbering );
            bytes = table < 0 ? -1 : bytes + table;
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t FleetSaveWire( const Ctx & ctx, const Fleet & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !FleetNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    // the root's own fields, then the node table's fields, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = FleetSaveBodyFields( ctx, numbering, w, root ) && TableNodeTableSave( ctx, w, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok ) { return -1; }
    w.put16( 0 );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == FleetMeasure( root )
}

inline int64_t FleetMeasure( const Fleet * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FleetMeasureWire( ctx, *root, allocator );
}

inline int64_t FleetSave( const Fleet * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FleetSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t FleetMeasure( const FleetBuilder & builder )
{
    if ( builder.region != NULL ) { return FleetMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FleetMeasureWire( ctx, *(const Fleet *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t FleetSave( const FleetBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return FleetSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FleetSaveWire( ctx, *(const Fleet *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// FleetLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t FleetLoadMeasure( const uint8_t * wire, int64_t wire_bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored );
    int64_t root_extent = 0;
    if ( !FleetWireExtent( wire, wire_bytes, root_extent ) ) { return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Fleet ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = FleetNodeStorage( type_id, length );
        if ( storage == kTableNodeRefused ) { return -1; } // an N the record's framing cannot carry (§2.8)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// FleetLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Fleet * FleetLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Fleet ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    int64_t root_extent = 0;
    if ( !FleetWireExtent( wire, wire_bytes, root_extent ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Fleet ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = FleetNodeStorage( type_id, length );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x0a53e00afba279afull;
    Fleet * root = new ( region ) Fleet; // lifetime only: LoadBody's first act is FleetReset
    FleetReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Fleet ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = FleetNodeStorage( type_id, length );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                FleetNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                FleetNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out );
    TableMapCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Fleet ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    FleetLoadBody( r, nodes, *root );
    return root;
}

// FleetLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool FleetLoadBuilder( FleetBuilder & builder, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    Fleet * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x0a53e00afba279afull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    nodes.worker = &builder.main; // and a map's entries are the arena's, not a node extent's (§2.8)
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = FleetNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                FleetNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out );
    TableMapCarve root_carve;
    root_carve.worker = &builder.main;
    nodes.carve = &root_carve;
    bool ok = FleetLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// ShipConfigOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// ShipConfig IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const ShipConfig * ShipConfigOpen( const void * bytes, uint64_t length )
{
    return (const ShipConfig *) TableCookOpen( bytes, length, (uint64_t) sizeof( ShipConfig ), (uint64_t) alignof( ShipConfig ) );
}

// ItemOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// Item IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Item * ItemOpen( const void * bytes, uint64_t length )
{
    return (const Item *) TableCookOpen( bytes, length, (uint64_t) sizeof( Item ), (uint64_t) alignof( Item ) );
}

// FleetOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// A REFERENCE INSIDE THE REGION IS DEREFERENCED THROUGH FleetAt: the slot holds
// the signed self-relative byte delta of §6.3, so a deref is one add and
// needs no base pointer, a whole region relocates by plain memcpy, and a
// delta of zero is null.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Fleet * FleetOpen( const void * bytes, uint64_t length )
{
    return (const Fleet *) TableCookOpen( bytes, length, (uint64_t) sizeof( Fleet ), (uint64_t) alignof( Fleet ) );
}

// ---- the cooked form: WRITE a cook (docs/SPEC-TABLES.md §7.6) ----
//
// The bytes are `schema cook`'s, and the tool stays the reference: the two
// writers are held to one file, byte for byte, in both byte orders. A cook is
// content-addressed by (asset hash, build version), so two writers of one
// instance produce ONE artifact or the pair means nothing.

inline void ShipConfigCookBody( uint8_t * at, const ShipConfig & value, TableByteOrder order );
inline void ItemCookBody( uint8_t * at, const Item & value, TableByteOrder order );
inline void FleetShipsEntryCookBody( uint8_t * at, const FleetShipsEntry & value, TableByteOrder order );
template <typename Ctx> inline bool FleetByIdEntryCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const FleetByIdEntry & value, TableByteOrder order );
inline void FleetLoadoutsEntryValueEntryCookBody( uint8_t * at, const FleetLoadoutsEntryValueEntry & value, TableByteOrder order );
template <typename Ctx> inline bool FleetLoadoutsEntryCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const FleetLoadoutsEntry & value, TableByteOrder order );
inline void FleetTiersEntryCookBody( uint8_t * at, const FleetTiersEntry & value, TableByteOrder order );
template <typename Ctx> inline bool FleetCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Fleet & value, TableByteOrder order );

inline void ShipConfigCookBody( uint8_t * at, const ShipConfig & value, TableByteOrder order )
{
    table_cook_bytes( at + 0, value.name, value.name_length, 65 );
    table_cook_put( at + 68, (uint64_t) (uint32_t) value.name_length, 4, order );
    table_cook_put( at + 72, (uint64_t) value.health, 4, order );
}

inline void ItemCookBody( uint8_t * at, const Item & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.count, 4, order );
}

inline void FleetShipsEntryCookBody( uint8_t * at, const FleetShipsEntry & value, TableByteOrder order )
{
    table_cook_bytes( at + 0, value.key, value.key_length, 33 );
    table_cook_put( at + 36, (uint64_t) (uint32_t) value.key_length, 4, order );
    ShipConfigCookBody( at + 40, value.value, order );
}

template <typename Ctx> inline bool FleetByIdEntryCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const FleetByIdEntry & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.key, 4, order );
    if ( !table_cook_ref( region, at + 8, (const void *) ShipConfigAt( ctx, value.value ), order ) ) { return false; } // value
    return true;
}

inline void FleetLoadoutsEntryValueEntryCookBody( uint8_t * at, const FleetLoadoutsEntryValueEntry & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.key, 1, order );
    ItemCookBody( at + 4, value.value, order );
}

template <typename Ctx> inline bool FleetLoadoutsEntryCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const FleetLoadoutsEntry & value, TableByteOrder order )
{
    (void) ctx; (void) region; // no reference below this node: the class was decided by a pointer elsewhere in its closure
    table_cook_bytes( at + 0, value.key, value.key_length, 17 );
    table_cook_put( at + 20, (uint64_t) (uint32_t) value.key_length, 4, order );
    table_cook_put( at + 24, 0, 8, order ); // value: the entry array's delta, filled by the extent writer
    table_cook_put( at + 32, 0, 4, order ); // and its count
    return true;
}

inline void FleetTiersEntryCookBody( uint8_t * at, const FleetTiersEntry & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.key, 2, order );
    ItemCookBody( at + 4, value.value, order );
}

template <typename Ctx> inline bool FleetCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Fleet & value, TableByteOrder order )
{
    table_cook_put( at + 0, 0, 8, order ); // ships: the entry array's delta, filled by the extent writer
    table_cook_put( at + 8, 0, 4, order ); // and its count
    table_cook_put( at + 16, 0, 8, order ); // by_id: the entry array's delta, filled by the extent writer
    table_cook_put( at + 24, 0, 4, order ); // and its count
    if ( !table_cook_ref( region, at + 32, (const void *) ShipConfigAt( ctx, value.flagship ), order ) ) { return false; } // flagship
    table_cook_put( at + 40, 0, 8, order ); // loadouts: the entry array's delta, filled by the extent writer
    table_cook_put( at + 48, 0, 4, order ); // and its count
    table_cook_put( at + 56, 0, 8, order ); // tiers: the entry array's delta, filled by the extent writer
    table_cook_put( at + 64, 0, 4, order ); // and its count
    return true;
}

template <typename Ctx> inline bool ShipConfigCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const ShipConfig & value, TableByteOrder order );
template <typename Ctx> inline bool ItemCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Item & value, TableByteOrder order );
template <typename Ctx> inline bool FleetShipsEntryCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const FleetShipsEntry & value, TableByteOrder order );
