template <typename Ctx> inline bool FleetLoadoutsEntryCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const FleetLoadoutsEntry & value, TableByteOrder order );
